export const concepts = [
  ['CPPL-R2-CON001', 'source file and executable', 'A .cpp file stores source text; the compiler and linker produce a separate executable that Windows can run.', '`g++ -std=c++20 -Wall -Wextra -Wpedantic banner.cpp -o banner.exe` builds before `.\\banner.exe` runs.', 'Assuming edited source is running merely because it is open in VS Code.'],
  ['CPPL-R2-CON002', 'compile and link stages', 'Each translation unit is compiled, then referenced definitions are connected during linking.', 'A declaration may compile while a missing definition produces an undefined-reference linker error.', 'Calling every build failure a syntax error.'],
  ['CPPL-R2-CON003', 'main and exit status', 'Execution starts in main, whose returned integer reports success or failure to the surrounding process.', '`return 0;` reports successful completion.', 'Treating printed text as the process exit status.'],
  ['CPPL-R2-CON004', 'diagnostic evidence', 'A warning or error gives a severity, source location, and message that should be read before editing.', 'A type-conversion warning identifies the source line and involved types.', 'Changing several lines before understanding the first relevant diagnostic.'],
  ['CPPL-R2-CON005', 'initialized typed value', 'A variable has a type, value, scope, and lifetime and should be initialized before its first read.', '`int weekly_minutes{360};` creates an initialized integer.', 'Reading an uninitialized local variable.'],
  ['CPPL-R2-CON006', 'stream insertion and formatting', 'The << operator sends values to an output stream in sequence; formatting state affects later numeric output.', '`std::cout << std::fixed << std::setprecision(1) << score;` controls decimal display.', 'Expecting commas inside a stream chain to behave like <<.'],
  ['CPPL-R2-CON007', 'complete-line input', 'std::getline reads one complete line, including internal spaces, and reports whether extraction succeeded.', '`std::getline(std::cin, name)` preserves a two-word name.', 'Mixing formatted extraction with getline and accidentally consuming a pending newline.'],
  ['CPPL-R2-CON008', 'numeric text parsing', 'A numeric input is valid only when conversion succeeds, the whole intended text is consumed, and the value is in range.', '`std::from_chars` can report both an error code and where parsing stopped.', 'Accepting `18cats` as the number 18.'],
  ['CPPL-R2-CON009', 'std::string value', 'std::string owns its text, tracks its size, and supports value comparison and concatenation.', '`course == "CSC 101"` compares text contents.', 'Treating string storage like a manually terminated character buffer.'],
  ['CPPL-R2-CON010', 'ordered branch', 'An if/else-if/else chain takes the first matching branch, so invalid cases belong before dependent success rules.', 'Reject an age outside the allowed range before testing eligibility.', 'Placing a broad success condition before a required rejection.'],
  ['CPPL-R2-CON011', 'short-circuit logic', '&& and || evaluate left to right and may skip the right side when the result is already known.', '`units > 0 && completed <= units` protects the second rule with the first.', 'Using a bitwise operator for a Boolean validation rule.'],
  ['CPPL-R2-CON012', 'loop progress', 'A loop needs deliberate initial state, a condition, and an update that can move the condition toward false.', 'A while loop removes one validated line from the input plan each iteration.', 'Updating the wrong value and creating an endless loop.'],
  ['CPPL-R2-CON013', 'vector size and index', 'A vector owns a dynamic sequence indexed from zero through size minus one.', '`scores.at(index)` checks the requested position.', 'Using index <= scores.size().'],
  ['CPPL-R2-CON014', 'range-based for', 'A range-based for visits each element when direct iterator or index control is unnecessary.', '`for (const int score : scores)` reads every score.', 'Copying a large object in a read-only loop without noticing.'],
  ['CPPL-R2-CON015', 'empty-range precondition', 'Some calculations need at least one value and must check emptiness before division, min, max, or dereference.', 'Return no summary until `scores.empty()` is false.', 'Dividing by size before checking for zero.'],
  ['CPPL-R2-CON016', 'function contract', 'A function contract states parameter types, return type, responsibility, and relevant preconditions.', '`double average(const std::vector<int>& values)` promises a calculated result without copying or mutation.', 'Combining input, calculation, storage, and printing in one function.'],
  ['CPPL-R2-CON017', 'value parameter and return', 'A value parameter is independent of its argument, and a value return gives the caller an owned result.', '`Plan normalized(Plan input)` can return a separate adjusted value.', 'Returning a reference to a local variable.'],
  ['CPPL-R2-CON018', 'const reference parameter', 'A const reference lets a function observe an existing object without copying or permitting mutation through that name.', '`const std::vector<int>& scores` provides read-only access.', 'Using a non-const reference for a function that should only inspect.'],
  ['CPPL-R2-CON019', 'header and translation unit', 'A header declares a shared interface; each .cpp file is compiled as its own translation unit before linking.', 'Both `main.cpp` and `planner.cpp` must be named in the g++ command.', 'Putting ordinary non-inline function definitions in a header and causing duplicate definitions.'],
  ['CPPL-R2-CON020', 'namespace', 'A namespace groups related names and avoids placing course functions in the global namespace.', '`campus::total_minutes(plan)` identifies its owner.', 'Writing `using namespace std;` in a header.'],
  ['CPPL-R2-CON021', 'constructor and invariant', 'A constructor establishes an object state that member functions can safely assume is valid.', '`Equipment{"Camera", 2}` begins with a nonblank label and nonnegative stock.', 'Constructing an invalid object and hoping later code repairs it.'],
  ['CPPL-R2-CON022', 'private state and const observer', 'Private fields change only through controlled member functions; const member functions promise not to alter observable state.', '`int available() const` reports stock without mutation.', 'Making fields public so callers can create negative stock.'],
  ['CPPL-R2-CON023', 'value ownership and copy independence', 'Standard-library values own their resources and clean them up automatically; copying a value creates an independently managed value.', 'Copying an Equipment object and changing the copy does not change the original.', 'Assuming two ordinary value objects secretly share the same fields.'],
  ['CPPL-R2-CON024', 'RAII lifetime', 'Resource acquisition is tied to object lifetime, so local streams and containers release their resources when scope ends.', 'An ofstream closes when its owning object leaves scope, while explicit close can expose final write failure.', 'Using new/delete for a beginner record that std::vector and std::string already own safely.'],
  ['CPPL-R2-CON025', 'iterator range', 'Standard algorithms operate on a half-open range from a first iterator up to but not including a last iterator.', '`std::sort(members.begin(), members.end(), predicate)` covers the whole vector.', 'Passing iterators from different containers.'],
  ['CPPL-R2-CON026', 'lambda capture', 'A lambda states its parameters and which surrounding values it may use.', '`[minimum](const Member& member) { return member.points >= minimum; }` captures one value.', 'Using `[&]` broadly and hiding which state controls the predicate.'],
  ['CPPL-R2-CON027', 'std::map keyed value', 'std::map stores unique keys in ordered lookup form and can summarize counts by category.', '`counts[course] += 1` intentionally inserts or increments a course count.', 'Using operator[] for a read-only lookup and accidentally inserting a missing key.'],
  ['CPPL-R2-CON028', 'file stream mode', 'ifstream reads and ofstream writes; opening an output file normally replaces its contents unless a safer replacement plan is used.', '`std::ifstream input{path};` never truncates the file.', 'Opening the live data path for output before validating all existing records.'],
  ['CPPL-R2-CON029', 'record parse contract', 'A persisted line is valid only when every required field, delimiter, and range is accepted.', '`id|topic|minutes` requires three complete fields and allowed values.', 'Loading a partial record and silently inventing the missing field.'],
  ['CPPL-R2-CON030', 'missing versus malformed storage', 'A missing first-run file may mean empty state, while an existing malformed or unreadable file must stop without replacement.', 'A confirmed absent tracker file starts empty; a bad line preserves the original file.', 'Treating every failed open as a harmless first run.'],
  ['CPPL-R2-CON031', 'debugger evidence', 'A breakpoint pauses one reproducible case so actual variables, container contents, and object state can be inspected before repair.', 'Pause before choosing next_id and inspect highest_id and candidate.', 'Adding random print statements and editing multiple causes at once.'],
  ['CPPL-R2-CON032', 'check harness', 'A small dependency-free check compares an actual result with a fixed expected contract and reports a visible pass or failure.', '`check_equal("next id", 4, actual)` protects a named rule.', 'Changing the expected result merely to make a broken implementation pass.'],
  ['CPPL-R2-CON033', 'argc and argv contract', 'argc counts command-line tokens and argv stores their text; count must be validated before indexing.', '`coursepilot.exe add "CSC 101" "Revise vectors"` supplies a command and two values.', 'Reading argv[2] before confirming it exists.'],
  ['CPPL-R2-CON034', 'reproducible C++ repository', 'A repository is reviewable when source, checks, safe samples, and README reproduce the build without generated or private files.', 'README records the exact C++20 build, run, and check commands.', 'Publishing .exe files, object files, secrets, personal records, or machine-specific editor paths.'],
].map(([id, term, simpleMeaning, example, commonMistake]) => ({ id, term, simpleMeaning, example, commonMistake }));

const build = ({ week, title, outcome, brief, competencyIds, priorKnowledgeCompetencyIds, conceptRefs, whyItMatters, steps, criteria, hints, templates, stretch, sessions, finishedResult }) => {
  const prefix = `CPPL-R2-B-W${String(week).padStart(2, '0')}-01`;
  return {
    id: prefix, title, required: true, outcome, competencyIds,
    estimatedMinutes: sessions.reduce((sum, session) => sum + session.minutes, 0), brief,
    steps: steps.map((text, index) => ({ id: `${prefix}-S${String(index + 1).padStart(2, '0')}`, text })),
    acceptanceCriteria: criteria.map((text, index) => ({ id: `${prefix}-A${String(index + 1).padStart(2, '0')}`, text })),
    hints,
    templates: templates.map((item, index) => ({ id: `${prefix}-T${String(index + 1).padStart(2, '0')}`, ...item })),
    stretch,
    learnerGuide: {
      summary: brief, whyItMatters, priorKnowledgeCompetencyIds, finishedResult, conceptRefs,
      sessions: sessions.map((session, index) => ({ id: `${prefix}-SESSION-${String(index + 1).padStart(2, '0')}`, title: session.title, estimatedMinutes: session.minutes, stepIds: session.stepIndexes.map((stepIndex) => `${prefix}-S${String(stepIndex).padStart(2, '0')}`) })),
    },
  };
};

