      templates: [{ label: 'Supplied integer helper', content: '#include <sstream>\n#include <string>\n\nbool parse_int_line(const std::string& text, int& result) {\n    std::istringstream input{text};\n    int candidate{};\n    if (!(input >> candidate)) {\n        return false;\n    }\n    input >> std::ws;\n    if (!input.eof()) {\n        return false;\n    }\n    result = candidate;\n    return true;\n}\n' }, { label: 'Classification contract', content: 'Validation:\n- name/course: nonblank\n- age: whole number 15..100\n- completed prerequisites: whole number 0..12\n- fee answer: yes or no\n\nCSC 101: age >= 16 and prerequisites >= 0\nCSC 102: age >= 16 and prerequisites >= 1\nOrder: INVALID -> NOT ELIGIBLE -> PENDING PAYMENT -> ELIGIBLE\n' }, { label: 'Six-case record', content: '| Case | Inputs | Expected | Actual | Pass? |\n| --- | --- | --- | --- | --- |\n| Spaced name, eligible paid | Mary Ann / CSC 101 / 18 / 0 / yes | ELIGIBLE | | |\n| Academic pass, unpaid | Tola / CSC 102 / 19 / 1 / no | PENDING PAYMENT | | |\n| Missing prerequisite | Kofi / CSC 102 / 19 / 0 / yes | NOT ELIGIBLE | | |\n| Age boundary below | Ada / CSC 101 / 15 / 0 / yes | NOT ELIGIBLE | | |\n| Extra numeric token | Uche / CSC 101 / 18 years / 0 / yes | INVALID AGE | | |\n| Unknown course | Lami / CSC 201 / 18 / 2 / yes | INVALID COURSE | | |\n' }],
      stretch: 'After all six cases pass, add a read-only explanation line naming the first unmet eligibility condition without changing the result labels.',
      sessions: [{ title: 'Read and validate complete input lines', minutes: 100, stepIndexes: [1, 2, 3] }, { title: 'Order decisions and repair a Boolean defect', minutes: 95, stepIndexes: [4, 5, 6] }],
      finishedResult: 'A six-case enrollment assistant with spaced-text support, fully checked integer parsing, ordered decisions, and a recorded short-circuit rule repair.',
