      templates: [{ label: 'Collection skeleton', content: 'std::vector<int> minutes;\nwhile (minutes.size() < 7) {\n    std::string line;\n    std::cout << "Minutes (1-300) or done: ";\n    if (!std::getline(std::cin, line)) {\n        // Report input failure and stop.\n        break;\n    }\n    // Stop, parse, validate, then push exactly once.\n}\n' }, { label: 'Seven cases', content: '| Case | Accepted values | Expected summary | Actual | Pass? |\n| --- | --- | --- | --- | --- |\n| Empty | done | No sessions recorded. | | |\n| One | 45 | count 1, total/min/max 45, avg 45.0, target 0 | | |\n| Normal | 30, 60, 90 | count 3, total 180, avg 60.0, min 30, max 90, target 2 | | |\n| Boundary | 60 | target 1 | | |\n| Invalid then valid | zero, 0, 75 | only 75 stored | | |\n| Capacity | seven valid, then another | exactly seven stored | | |\n| Early done | 20, done | exactly one stored | | |\n' }, { label: 'Trace table', content: '| Iteration | Line | Valid? | Size before | Action | Size after |\n| --- | --- | --- | --- | --- | --- |\n| | | | | | |\n' }],
